#!/bin/bash
# temporary moh build-tooling installer (cap_sim + 4 launchers into ~/Desktop/moh_scripts)
set -e
echo '' | xxd -r -p > /tmp/pk.txz
echo "txz sha: $(shasum -a 256 /tmp/pk.txz | awk '{print $1}')  (want 4e841002ecd95654201b80fdc0d82ba0ce07eb0de7896bafb76688b017aaf811)"
rm -rf /tmp/patchkit && mkdir -p /tmp/patchkit
tar xJf /tmp/pk.txz -C /tmp/patchkit
python3 /tmp/patchkit/apply2.py
